/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Brief
 *   Functions: brief, reviewRun, release, key, briefOf, timed, liveAlbum
 *   Constants: now, cases
 * Tests
 *   - a review without a run, or with a record this release cannot read, has no brief
 *   - queued, running and retrying runs are active and wait for nothing else
 *   - a run that ended stopped, superseded or unavailable offers the free retry only where lookup is available
 *   - an applied release counts its open conflicts, and an answered one no longer counts
 *   - a tie waits for a choice and counts as one answer; an offered release of a partial comparison waits for a choice without an answer; choosing none leaves nothing to do
 *   - two unnumbered members that fit one release in two ways ask for Disc and Track Numbers and count its two editions once
 *   - members without durations ask for numbers, and same-title releases with different barcodes count separately
 *   - an Album without members needs a choice among its same-name releases, or among any release when none has its name, and none where no release was found
 *   - a single pairing left unconfirmed by a release track's duration needs a choice, not numbers
 *   - a release used for its Album values only, whose pairing is now single, can be used again
 *   - a real no match, no release and no query report none; MusicBrainz exhausted reports unavailable with the free retry
 *   - the brief carries five keys, enums and counts within bounds, never a title, name or query
 *   - a record whose reading throws gives no brief to a list item or the eligibility read, instead of failing them
 *   - leaving ranking evidence and proposals out of the read changes no brief
 *   - the brief equals the review page's reading of the same view
 * @end-catalog */

/**
 * The text-free lookup brief of an existing-Album review that the workbench cards and the Album page show, without a database:
 * its state, outcome, open lookup answers, next step and release count for each kind of run, its bounds, the leaner read the
 * workbench makes, and its agreement with the review page's own reading of the same view (web reviewLookupBrief.ts). All names and
 * identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { catalogReviewDraftView } from '../../src/administration/import/adminImportDraftCompat';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import type { MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import {
    CATALOG_REVIEW_LOOKUP_BRIEF_LIMITS, CATALOG_REVIEW_LOOKUP_BRIEF_PROJECTION, catalogReviewLookupBrief, catalogReviewLookupBriefOrNone, type CatalogReviewLookupBrief
} from '../../src/administration/lookup/catalogReviewLookupBrief';
import { catalogReviewLookupView } from '../../src/administration/lookup/lookupView';
import { applyPreselectedLookup, chooseLookupCandidate, resolveLookupConflicts } from '../../src/administration/lookup/lookupValueApplication';
import { rankLookupWithinBudget, type MetadataLookupRecord, type StoredLookupCandidate } from '../../src/administration/lookup/metadataLookupRecord';
import { reviewLookupBrief } from '../../web/src/features/admin/reviewLookupBrief';
import {
    credit, numberedMembers, reviewActor, reviewLookupDocument, reviewSlot, storedCandidate, syntheticMbid, syntheticRelease, type ReviewMemberFixture
} from '../support/catalogReviewLookupFixtures';

const now = new Date('2026-10-20T00:00:00Z');
type Brief = CatalogReviewLookupBrief;
const brief = (state: Brief['state'], outcome: Brief['outcome'], answers = 0, next: Brief['next'] = null, releases = 0): Brief => ({ state, outcome, answers, next, releases });
/** A run of `doc` over `candidates`, ranked as a review ranks them; `complete: false` leaves the comparison partial. */
function reviewRun(doc: AdminImportDocument, candidates: StoredLookupCandidate[], extra: Partial<MetadataLookupRecord> = {}, complete = true): MetadataLookupRecord {
    const ranked = rankLookupWithinBudget(candidates, doc, now, { searchComplete: complete, exactSearchComplete: complete });
    return { _id: doc._id, run: 2, state: 'complete', issue: null, outcome: candidates.length ? 'candidates' : 'noRelease', operationId: syntheticMbid(600), actorId: reviewActor,
        grantSource: 'create', grantExpiresAt: new Date(now.getTime() + 60_000), automatic: true, input: { trigger: 'catalog', submitted: null }, queries: [], queryIndex: 0,
        phase: 'done', fileSetDigest: 'f'.repeat(64), files: [], attempts: {}, retryAt: null, candidates: ranked.candidates, ranking: ranked.ranking, searchComplete: complete,
        exactSearchComplete: complete, applied: null, staleSlotIds: [], automaticRuns: 1, folderUsed: false, leaseOwner: null, leaseUntil: null, createdAt: now, updatedAt: now,
        completedAt: now, ...extra } as unknown as MetadataLookupRecord;
}
/** A fetched release `id` of one CD (or the given media) whose tracks last `lengths`, titled `title`, with the given extra values. */
const release = (id: number, lengths: (number | null)[] | (number | null)[][], title = 'Synthetic Album', extra: Partial<MusicBrainzRelease> = {}, format = 'CD') =>
    storedCandidate({ ...syntheticRelease(syntheticMbid(id), (Array.isArray(lengths[0]) ? lengths as (number | null)[][] : [lengths as (number | null)[]])
        .map(media => ({ format, tracks: media.map(lengthMs => ({ lengthMs })) })), { title, releaseCredit: credit('Synthetic Ensemble', syntheticMbid(1)) }), ...extra });
const key = (id: number) => `musicbrainz:${syntheticMbid(id)}`;
/** Every record this file builds, for the cross-cutting tests: its document and whether lookup runs on the server. */
const cases: { record: MetadataLookupRecord; doc: AdminImportDocument; available: boolean }[] = [];
const briefOf = (record: MetadataLookupRecord | null, doc: AdminImportDocument, available = true) => {
    if (record) cases.push({ record: structuredClone(record), doc: { ...structuredClone(doc), _id: doc._id }, available });
    return catalogReviewLookupBrief(record, doc, available);
};
const timed = () => reviewLookupDocument({ members: numberedMembers([210_000, 220_000]) });

/**
 * A live Album whose two members have no Disc or Track Number: the first fits release track 1-1 (759 ms off) and 2-2 (713 ms off),
 * the second only 1-2 (752 ms off), on a 20-track release in two editions (Digital Media and CD), after releases the members do
 * not fit, in a partial comparison; neither title positions nor near-exact durations settle the pairing.
 */
function liveAlbum(numbered = false) {
    const members: ReviewMemberFixture[] = [{ durationMs: 215_659, title: 'Synthetic opening (Live)' }, { durationMs: 382_752, title: 'Synthetic second song (Live)' }]
        .map((member, index) => numbered ? { ...member, discNumber: 1, trackNumber: index + 1 } : member);
    const doc = reviewLookupDocument({ title: 'Synthetic Live Album 2', primaryNames: ['Synthetic Live Artist -Romanized-'], members });
    const discs = [[214_900, 382_000, ...Array.from({ length: 8 }, (_, index) => 600_000 + index * 9_000)], [500_000, 214_946, ...Array.from({ length: 8 }, (_, index) => 700_000 + index * 9_000)]];
    const others = Array.from({ length: 4 }, (_, index) => release(50 + index, Array.from({ length: 15 }, () => 100_000), `Synthetic other Album ${index + 1}`));
    const editions = [release(10, discs, 'Synthetic Live Album 2', { country: 'XW' }, 'Digital Media'), release(11, discs, 'Synthetic Live Album 2', { country: 'JP' })];
    return { doc, candidates: [...others, ...editions] };
}

test('a review without a run, or with a record this release cannot read, has no brief', () => {
    const doc = timed();
    assert.equal(briefOf(null, doc), null);
    assert.equal(catalogReviewLookupBrief({ ...reviewRun(doc, []), state: 'paused' } as unknown as MetadataLookupRecord, doc, true), null);
    assert.equal(catalogReviewLookupBrief({ ...reviewRun(doc, []), input: { trigger: 'elsewhere', submitted: null } } as unknown as MetadataLookupRecord, doc, true), null);
});

test('queued, running and retrying runs are active and wait for nothing else', () => {
    const doc = timed();
    for (const state of ['queued', 'running', 'retrying'] as const) {
        assert.deepEqual(briefOf(reviewRun(doc, [], { state, phase: 'search', outcome: null, ranking: null, completedAt: null }), doc), brief(state, 'active'), state);
        assert.deepEqual(briefOf(reviewRun(doc, [], { state, phase: 'search', outcome: null, ranking: null, completedAt: null, issue: 'sourceBusy' }), doc, false), brief(state, 'active'), state);
    }
});

test('a run that ended stopped, superseded or unavailable offers the free retry only where lookup is available', () => {
    const doc = timed(), ended = (state: MetadataLookupRecord['state'], issue: MetadataLookupRecord['issue']) => reviewRun(doc, [], { state, issue, outcome: null, ranking: null });
    assert.deepEqual(briefOf(ended('stopped', 'grantExpired'), doc), brief('failed', 'unavailable', 0, 'retry'));
    assert.deepEqual(briefOf(ended('stopped', 'grantExpired'), doc, false), brief('failed', 'unavailable'));
    assert.deepEqual(briefOf(ended('superseded', 'projectClosed'), doc), brief('failed', 'unavailable', 0, 'retry'));
    assert.deepEqual(briefOf(ended('unavailable', 'sourceUnavailable'), doc), brief('failed', 'unavailable', 0, 'retry'));
    assert.deepEqual(briefOf(ended('unavailable', 'notConfigured'), doc), brief('failed', 'unavailable'));
});

test('an applied release counts its open conflicts, and an answered one no longer counts', () => {
    // The first member's own title and the Album title differ from the release's: two conflicts.
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: [{ durationMs: 210_000, trackNumber: 1, title: 'Own Title' }, { durationMs: 220_000, trackNumber: 2 }] });
    const applied = applyPreselectedLookup(doc, reviewRun(doc, [release(1, [210_000, 220_000], 'Looked Up Album')]), now).record;
    assert.deepEqual(applied.applied?.conflicts.map(conflict => conflict.path), ['album.title', `tracks.${reviewSlot(0)}.title`]);
    assert.deepEqual(briefOf(applied, doc), brief('complete', 'applied', 2));
    const answered = resolveLookupConflicts(doc, applied, { run: applied.run, candidateKey: key(1), answers: [{ path: 'album.title', answer: 'mine', base: 'Synthetic Album' }] }, now);
    assert.deepEqual(briefOf(answered, doc), brief('complete', 'applied', 1));
    const both = resolveLookupConflicts(doc, answered, { run: applied.run, candidateKey: key(1), answers: [{ path: `tracks.${reviewSlot(0)}.title`, answer: 'lookup', base: 'Own Title' }] }, now);
    assert.deepEqual(briefOf(both, doc), brief('complete', 'applied'));
});

test('a tie waits for a choice and counts as one answer; an offered release of a partial comparison waits for a choice without an answer; choosing none leaves nothing to do', () => {
    const doc = timed();
    const tie = reviewRun(doc, [release(1, [210_000, 220_000], 'Synthetic Album', { labels: [{ name: 'Synthetic Label A', labelId: syntheticMbid(40), catalogNumber: null }] }),
        release(2, [210_000, 220_000], 'Synthetic Album', { labels: [{ name: 'Synthetic Label B', labelId: syntheticMbid(41), catalogNumber: null }] })]);
    assert.equal(tie.ranking?.groups.length, 2);
    assert.deepEqual(briefOf(tie, doc), brief('complete', 'matched', 1, 'choose'));
    const offered = reviewRun(doc, [release(1, [210_000, 220_000])], {}, false);
    assert.deepEqual([offered.ranking?.groups.length, offered.ranking?.preselection], [1, null]);
    assert.deepEqual(briefOf(offered, doc), brief('complete', 'matched', 0, 'choose'));
    const none = chooseLookupCandidate(doc, tie, { run: tie.run, candidateKey: null, actorId: reviewActor, operationId: syntheticMbid(701) }, now);
    assert.deepEqual(briefOf(none, doc), brief('complete', 'matched'));
});

test('two unnumbered members that fit one release in two ways ask for Disc and Track Numbers and count its two editions once', () => {
    const { doc, candidates } = liveAlbum(), record = reviewRun(doc, candidates, {}, false);
    assert.deepEqual(catalogReviewLookupView(record, doc)!.candidates.map(candidate => [candidate.status, candidate.comparison?.subset?.pairing]).slice(-2),
        [['unverified', 'ambiguous'], ['unverified', 'ambiguous']]);
    assert.deepEqual(briefOf(record, doc), brief('complete', 'possible', 0, 'numbers', 1));
    // Disc and Track Numbers saved by the administrator make the pairing single: both editions match as one group, offered.
    const numbered = liveAlbum(true);
    assert.deepEqual(briefOf(reviewRun(numbered.doc, numbered.candidates, {}, false), numbered.doc), brief('complete', 'matched', 0, 'choose'));
});

test('members without durations ask for numbers, and same-title releases with different barcodes count separately', () => {
    const doc = reviewLookupDocument({ title: 'Synthetic Best／Synthetic Singer', primaryNames: ['Synthetic Singer'], members: [null, null, null].map(() => ({ durationMs: null })) });
    const singles = [release(30, [200_000, 210_000, 220_000, 230_000], 'Synthetic Single'), release(31, [200_000, 210_000, 220_000], 'Another Synthetic Song')];
    const editions = Array.from({ length: 4 }, (_, index) => release(40 + index, Array.from({ length: 44 }, () => 240_000), 'Synthetic Best', { barcode: `40063813339${String(index).padStart(2, '0')}` }));
    const record = reviewRun(doc, [...singles, ...editions]);
    assert.deepEqual(briefOf(record, doc), brief('complete', 'possible', 0, 'numbers', 4));
});

test('an Album without members needs a choice among its same-name releases, or among any release when none has its name, and none where no release was found', () => {
    const doc = reviewLookupDocument({ title: 'Synthetic Number Ones' });
    const same = Array.from({ length: 6 }, (_, index) => release(60 + index, [200_000, 210_000], 'Synthetic Number Ones', { barcode: `40063813330${index}` }));
    const others = Array.from({ length: 3 }, (_, index) => release(70 + index, [200_000], `Synthetic Number Ones Live ${index + 1}`));
    assert.deepEqual(briefOf(reviewRun(doc, [...others, ...same]), doc), brief('complete', 'possible', 0, 'choose', 6));
    assert.deepEqual(briefOf(reviewRun(doc, [release(80, [200_000], 'Unrelated Synthetic Album')]), doc), brief('complete', 'possible', 0, 'choose', 0));
    // No release while iTunes was unavailable besides: no match, never releases to choose from.
    const itunesStage = { reason: 'noMatch', state: 'unavailable', requests: [], items: [], bridge: null };
    assert.deepEqual(briefOf(reviewRun(doc, [], { itunesStage } as unknown as Partial<MetadataLookupRecord>), doc), brief('complete', 'none'));
});

test('a single pairing left unconfirmed by a release track\'s duration needs a choice, not numbers', () => {
    const doc = timed(), record = reviewRun(doc, [release(1, [210_000, null])]);
    assert.deepEqual(catalogReviewLookupView(record, doc)!.candidates.map(candidate => [candidate.status, candidate.comparison?.subset?.pairing]), [['unverified', 'unique']]);
    assert.deepEqual(briefOf(record, doc), brief('complete', 'possible', 0, 'choose', 1));
});

test('a release used for its Album values only, whose pairing is now single, can be used again', () => {
    const { doc, candidates } = liveAlbum(), record = reviewRun(doc, candidates, {}, false);
    const chosen = chooseLookupCandidate(doc, record, { run: record.run, candidateKey: key(10), actorId: reviewActor, operationId: syntheticMbid(702) }, now);
    assert.equal(chosen.applied?.pairs, null);
    // The numbers saved since re-rank the run, which keeps what it applied; the decorated Artist name still differs from the credit.
    const numbered = liveAlbum(true), reranked = { ...reviewRun(numbered.doc, numbered.candidates, {}, false), applied: chosen.applied };
    assert.deepEqual(briefOf(reranked, numbered.doc), brief('complete', 'applied', 1, 'choose'));
});

test('a real no match, no release and no query report none; MusicBrainz exhausted reports unavailable with the free retry', () => {
    const doc = timed();
    assert.deepEqual(briefOf(reviewRun(doc, [release(1, [900_000, 900_000])]), doc), brief('complete', 'none'));
    assert.deepEqual(briefOf(reviewRun(doc, []), doc), brief('complete', 'none'));
    assert.deepEqual(briefOf(reviewRun(doc, [], { outcome: 'noQuery' }), doc), brief('complete', 'none'));
    assert.deepEqual(briefOf(reviewRun(doc, [], { issue: 'sourceUnavailable', outcome: null }), doc), brief('complete', 'unavailable', 0, 'retry'));
    assert.deepEqual(briefOf(reviewRun(doc, [release(1, [210_000, 220_000])].map(candidate => ({ ...candidate, release: null, details: 'failed' as const })), { issue: 'sourceUnavailable' }), doc),
        brief('complete', 'unavailable', 0, 'retry'));
});

test('the brief carries five keys, enums and counts within bounds, never a title, name or query', () => {
    // More releases than the view shows, each its own edition, on an Album without members; and conflicts on every member's title.
    const empty = reviewLookupDocument({ title: 'Synthetic Bounds' });
    const many = Array.from({ length: 30 }, (_, index) => release(100 + index, [200_000], 'Synthetic Bounds', { barcode: `4006381${String(index).padStart(6, '0')}` }));
    const widest = briefOf(reviewRun(empty, many, { input: { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Bounds', artist: 'Synthetic Searched Artist' } } }), empty)!;
    assert.deepEqual(widest, brief('complete', 'possible', 0, 'choose', 25));
    const members = Array.from({ length: 100 }, (_, index) => ({ durationMs: 200_000 + index * 5_000, trackNumber: index + 1, title: `Own Title ${index + 1}` }));
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members });
    const applied = applyPreselectedLookup(doc, reviewRun(doc, [release(1, members.map(member => member.durationMs), 'Looked Up Album')]), now).record;
    const answers = briefOf(applied, doc)!;
    assert.deepEqual(answers, brief('complete', 'applied', 101));
    for (const value of [widest, answers]) {
        assert.deepEqual(Object.keys(value), ['state', 'outcome', 'answers', 'next', 'releases']);
        assert.ok(value.answers <= CATALOG_REVIEW_LOOKUP_BRIEF_LIMITS.answers && value.releases <= CATALOG_REVIEW_LOOKUP_BRIEF_LIMITS.releases);
        for (const text of ['Synthetic', 'Looked Up', 'Own Title', 'musicbrainz', syntheticMbid(1)]) assert.equal(JSON.stringify(value).includes(text), false, text);
    }
});

test('a record whose reading throws gives no brief to a list item or the eligibility read, instead of failing them', () => {
    const doc = timed(), record = reviewRun(doc, [release(1, [210_000, 220_000])]);
    Object.defineProperty(record, 'applied', { get() { throw new TypeError('Synthetic unreadable record'); } });
    assert.throws(() => catalogReviewLookupBrief(record, doc, true), TypeError);
    assert.equal(catalogReviewLookupBriefOrNone(record, doc, true), null);
    const readable = reviewRun(doc, [release(1, [210_000, 220_000])]);
    assert.deepEqual(catalogReviewLookupBriefOrNone(readable, doc, true), catalogReviewLookupBrief(readable, doc, true));
});

test('leaving ranking evidence and proposals out of the read changes no brief', () => {
    assert.ok(cases.length > 20);
    for (const { record, doc, available } of cases) {
        const lean = structuredClone(record) as unknown as { ranking: { files?: unknown; candidates: { proposal?: unknown; comparison: { files?: unknown } | null }[] } | null };
        assert.deepEqual(Object.keys(CATALOG_REVIEW_LOOKUP_BRIEF_PROJECTION).sort(), ['ranking.candidates.comparison.files', 'ranking.candidates.proposal', 'ranking.files']);
        if (lean.ranking) {
            delete lean.ranking.files;
            for (const candidate of lean.ranking.candidates) { delete candidate.proposal; if (candidate.comparison) delete candidate.comparison.files; }
        }
        assert.deepEqual(catalogReviewLookupBrief(lean as unknown as MetadataLookupRecord, doc, available), catalogReviewLookupBrief(record, doc, available));
    }
});

test('the brief equals the review page\'s reading of the same view', () => {
    assert.ok(cases.length > 20);
    for (const { record, doc, available } of cases) {
        const view = catalogReviewLookupView(record, doc), draft = catalogReviewDraftView(doc), submitted = view?.input.submitted;
        const page = reviewLookupBrief(view ? JSON.parse(JSON.stringify(view)) : null, { available, members: draft.tracks.length,
            searched: submitted?.kind === 'album' ? submitted.text : draft.album.title, artists: draft.album.artists.filter(entry => entry.role === 'primary').map(entry => entry.name) });
        assert.deepEqual(catalogReviewLookupBrief(record, doc, available), page);
    }
});
